import { Link } from 'react-router-dom';
import { MAX_BOX } from '@lexpad/core';
import { BoxMeter } from '@/components/ui/BoxMeter.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { HOW_FOCUS, settingsPath } from '@/features/settings/paths.js';
import styles from './StepLink.module.css';

/** Where every "Step 2 of 5" leads: How Lexpad works, at its part about the steps. */
export const STEP_HOW_PATH = `${settingsPath('how')}#${HOW_FOCUS.boxes}`;

/**
 * A word's step, drawn and named ("Step 2 of 5"), as a link to How Lexpad
 * works (app audit 2026-10-22): the five steps are the model the whole app
 * runs on, and the page that explains them was three taps away. For places
 * that are not themselves inside a link or a session.
 */
export function StepLink({
  box,
  className,
}: {
  box: number;
  className?: string | undefined;
}): React.JSX.Element {
  const at = Math.min(Math.max(Math.round(box), 1), MAX_BOX);
  return (
    <Link
      to={STEP_HOW_PATH}
      className={cx(styles.link, className)}
      aria-label={t('word.stepHow', { box: at, total: MAX_BOX })}
    >
      <BoxMeter box={at} label />
    </Link>
  );
}
